window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q414","domains":[1],"level":4,"tag":"","q":"A prototype for a hospital discharge workflow reveals that pharmacists must flag dangerous interactions before prescriptions are released. The approved scope covers discharge summaries only. What is the best next step?","opts":["Add the capability because the prototype demonstrated its relevance","Treat the flag as a design detail and record it in the interface specification","Reject the finding because the approved scope is the controlling baseline","Document the need, assess its scope and stakeholder impact, and use the agreed change decision process."],"answer":[3],"why":["Prototype evidence does not itself authorize scope expansion.","The finding concerns a stakeholder need and should not be reduced to a design detail.","A baseline controls changes but does not justify ignoring relevant new information.","Correct: evaluate and govern the finding as a potential scope change rather than automatically accepting or dismissing it."],"ref":"BABOK v3 §2.4 p. 19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q415","domains":[1],"level":5,"tag":"","q":"A bank's new fraud alert ships on time. Alerts increase, losses stay flat, and legitimate purchases are increasingly blocked. Which assessment is most defensible?","opts":["Value is mixed or unproven; assess intended and unintended outcomes across stakeholders and context","The initiative created value because the planned feature was delivered","The initiative failed because the loss measure did not improve","The solution succeeded if alert volume meets its acceptance threshold"],"answer":[0],"why":["Correct: assess value in context, including intended outcomes and unintended consequences.","Delivery of a feature is not proof of stakeholder value.","One unchanged outcome alone does not establish overall failure; the blocking impact also needs analysis.","Acceptance criteria confirm specified delivery, not overall business value."],"ref":"BABOK v3 §§2.1–2.4 pp. 12–19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q416","domains":[1],"level":1,"tag":"","q":"A utility's outage initiative has a target to restore power faster. Which item is most clearly a business requirement?","opts":["Allow a dispatcher to reassign crews from a tablet","Reduce average outage restoration time by 20% within the next year.","Display crew location updates within 30 seconds","Convert active outage records to the new platform before cutover"],"answer":[1],"why":["This describes a solution capability, not the business objective.","Correct: states an organizational outcome; the other choices describe solution behavior, performance, or transition work.","This is a solution performance requirement.","This is a transition requirement needed for implementation."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q417","domains":[1],"level":2,"tag":"","q":"A prototype of a procurement dashboard makes buyers ask to compare negotiated and paid prices. What should the BA do with the discovery?","opts":["Add a design element to the dashboard and assume the need is covered","Replace the original requirement because the prototype is more current","Clarify the buyer need behind the comparison request, then assess it alongside the existing requirement.","Defer it as a change request until all design work is complete"],"answer":[2],"why":["A visual element does not fully express or validate the underlying need.","The new need does not automatically invalidate the original requirement.","Correct: explores the underlying need without assuming a design or invalidating an existing requirement.","There is no need to wait until design completion to assess a newly discovered need."],"ref":"BABOK v3 §2.4 p. 19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q418","domains":[1],"level":3,"tag":"","q":"A university modernization has a goal to improve course completion, a student need to see remaining degree requirements, and a system capability to show a degree audit. Which classification is correct?","opts":["Goal: solution requirement; need: business requirement; capability: stakeholder requirement","Goal: stakeholder requirement; need: solution requirement; capability: business requirement","Goal: transition requirement; need: business requirement; capability: non-functional requirement","Goal: business requirement; need: stakeholder requirement; capability: solution requirement"],"answer":[3],"why":["This reverses organizational objective, stakeholder need, and solution capability.","The course-completion goal is not a stakeholder-level requirement, and the need is not a system function.","None of these items describes a transition capability or quality attribute.","Correct: the goal is an organizational objective, the need is a stakeholder need, and the capability describes the solution."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q419","domains":[1],"level":4,"tag":"","q":"A regulator changes a reporting rule. The team finds three related requirements, two designs, and a test case, but one downstream report has no linked source requirement. What does this most strongly indicate?","opts":["Traceability has exposed a possible gap or unsupported design that should be investigated","The new regulator rule should be approved before any trace links are updated","The report is automatically invalid because every design must link directly to a business requirement","The test case should become the source requirement because it already verifies the report"],"answer":[0],"why":["Correct: tracing helps identify gaps, impacts, and design elements without supporting requirements.","Change approval and impact traceability are related, but this does not address the discovered unsupported report.","Traceability can connect through multiple levels; a direct link to a business requirement is not always required.","A test case verifies behavior; it does not replace the requirement that justifies it."],"ref":"BABOK v3 §5.1 pp. 79–82; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q420","domains":[1],"level":5,"tag":"","q":"A safety rule changes after requirements are approved. A linked user story, interface design, vendor contract, and training plan may all be affected. What should the BA do before recommending acceptance?","opts":["Update the story and let each team identify its own impacts during delivery","Trace the change through related requirements, designs, contracts, and training; assess impacts and route any proposed change for decision.","Reject it because approved requirements should remain stable for the release","Ask the vendor to estimate the interface change and use that estimate as the impact assessment"],"answer":[1],"why":["Updating one item without broader traceability risks missing consequential impacts.","Correct: traceability supports full impact analysis and controlled decisions before changes are made.","Approval does not make requirements immune to changed context or safety obligations.","An estimate covers only one aspect and cannot stand in for full impact analysis."],"ref":"BABOK v3 §§5.1, 5.4 pp. 79–82, 91–94; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q421","domains":[2],"level":1,"tag":"","q":"A lending model meets its overall approval target but rejects a much higher share of applicants with limited credit history. The sponsor requests only aggregate results. What should the BA do?","opts":["Report the aggregate and postpone segment review until production","Recommend deployment because the model met its approved target","Analyze and report subgroup outcomes alongside the aggregate, then assess impacts and response options with relevant stakeholders.","Ask the sponsor to decide whether the subgroup is relevant before documenting it"],"answer":[2],"why":["Postponing relevant evidence could conceal material stakeholder impacts.","Meeting an aggregate target does not resolve unequal subgroup outcomes.","Correct: segment results may reveal material effects hidden by aggregate performance and should inform the assessment.","The BA should document relevant evidence without waiting for permission to consider it."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q422","domains":[2],"level":2,"tag":"","q":"Operations calls a new policy urgent when it means same-day action; finance means action before the next monthly close. What is the best BA response?","opts":["Use the sponsor's interpretation as the shared definition","Record both uses as synonyms so each team can retain its language","Choose the stricter meaning to minimize potential exposure","Clarify what “urgent” means operationally for each group, then agree and document a usable definition or decision rule."],"answer":[3],"why":["Sponsor seniority does not resolve the different operational meanings.","Treating distinct deadlines as synonyms can create inconsistent behavior.","A stricter interpretation may create unnecessary cost or conflict with policy intent.","Correct: distinct deadlines need explicit definitions so teams act consistently."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q423","domains":[2],"level":3,"tag":"","q":"A warehouse redesign reduces picking time in one site but increases replenishment errors and overtime in a second site. Which mindset should guide the assessment?","opts":["Examine relationships and downstream effects across connected processes and stakeholders","Optimize the site sponsoring the redesign and track the other site separately","Treat the second site's impact as out of scope because its manager was not a requester","Keep the original measure and investigate downstream effects only if it misses target"],"answer":[0],"why":["Correct: systems thinking examines effects across connected processes and stakeholder groups.","Local optimization can shift costs and risks elsewhere in the system.","An impacted group can be relevant even if it did not initiate the change.","Known effects warrant investigation before they become target failures."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q424","domains":[2],"level":4,"tag":"","q":"New frontline evidence contradicts the BA's earlier recommendation. The steering group has already endorsed that recommendation. What is the most professional response?","opts":["Retain the recommendation until the steering group formally reopens it","Reassess the recommendation against the new evidence, document any changed conclusion, and inform the steering group.","Replace it with the frontline team's preferred option to reflect the latest evidence","Exclude the new evidence because the earlier decision established scope"],"answer":[1],"why":["Endorsement does not make an evidence-based recommendation immune to revision.","Correct: professional analysis incorporates relevant new evidence and communicates its effect, even after endorsement.","The evidence should be assessed; stakeholder preference alone is not sufficient analysis.","Scope governance does not justify suppressing relevant information."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q425","domains":[2],"level":5,"tag":"","q":"A proprietary screening model improves speed, but neither the vendor nor internal team can explain some rejections. What should the BA recommend?","opts":["Accept it if the vendor meets the contractual accuracy commitment","Treat explainability as technical detail and compare only throughput","Assess explainability and related fairness and accountability risks with affected stakeholders before recommending adoption.","Request an explanation after implementation once a larger sample is available"],"answer":[2],"why":["Contract performance does not settle fairness, transparency, or accountability concerns.","Explainability can affect stakeholder outcomes and risk, not just technical design.","Correct: unexplained consequential decisions create stakeholder and business risks that speed or accuracy alone do not resolve.","Waiting until after implementation may make material harm harder to prevent or correct."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q426","domains":[2],"level":1,"tag":"","q":"A BA hears a stakeholder say the process is fine while the stakeholder repeatedly hesitates around handoffs. What is the most useful next move?","opts":["Record the process as acceptable and proceed to the next topic","Explain the documented handoff process and ask if that is what they meant","Infer dissatisfaction and log the stakeholder as resistant","Ask an open question about the hesitation and handoffs, then confirm the stakeholder’s meaning without suggesting an answer."],"answer":[3],"why":["This records the literal word but ignores a cue that may affect meaning.","Providing an interpretation can bias the response.","Hesitation alone does not establish dissatisfaction or resistance.","Correct: a neutral follow-up explores the cue without imposing an interpretation."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q427","domains":[2],"level":3,"tag":"","q":"A BA receives confidential pricing data during an interview, then notices the workshop pack is scheduled to be shared with a broad partner group. What is the best action?","opts":["Check authorization and handling requirements, limit disclosure appropriately, and tell the relevant owner what must be changed","Share the pack because attendees have a legitimate project interest","Remove all pricing information and continue without telling the source","Ask the partner group to keep the pack confidential after distribution"],"answer":[0],"why":["Correct: protect confidential information and follow authorized access and handling requirements.","Project interest does not automatically authorize disclosure of confidential information.","The information may be needed by authorized decision-makers; remove or redact based on applicable rules.","A confidentiality request does not substitute for preventing unauthorized disclosure."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q428","domains":[3],"level":1,"tag":"","q":"A regulator requires a fixed data migration date, while customer-facing features will evolve through pilot feedback. Which BA approach is most appropriate?","opts":["Use adaptive practices throughout because the features are uncertain","Use a tailored or hybrid approach: plan the fixed migration predictively while adapting customer-facing features through pilot feedback.","Use predictive practices throughout because the regulator sets the program deadline","Delay approach planning until customer feature requirements are stable"],"answer":[1],"why":["Feature uncertainty does not remove the need to plan the fixed migration.","Correct: the approach can fit different levels of certainty and constraint within one change.","A fixed deadline does not mean all requirements are stable or best handled predictively.","Approach planning should help manage uncertainty rather than wait for it to disappear."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q429","domains":[3],"level":3,"tag":"","q":"A distributed change includes a busy frontline group, an external vendor, and a regulator who reviews only formal submissions. What should the stakeholder engagement plan specify?","opts":["One communication cadence and one review format to ensure consistency","A workshop for every stakeholder so the same information reaches all groups","Tailor engagement methods and timing to each group’s role, access, decision needs, and formal review obligations.","The regulator's formal review dates, with other engagement left to individual teams"],"answer":[2],"why":["Uniformity may not fit different roles, access needs, or decision responsibilities.","A workshop may not suit every stakeholder, especially formal or external reviewers.","Correct: planned engagement should fit each stakeholder and coordinate formal reviews with ongoing involvement.","The plan should coordinate engagement across all relevant stakeholders, not leave gaps to chance."],"ref":"BABOK v3 §3.2 pp. 31–36; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q430","domains":[3],"level":5,"tag":"","q":"A product owner can rank features, compliance approves control interpretation, and architecture approves enterprise integration exceptions. One release item needs all three. What is the best governance approach?","opts":["Ask the product owner to decide the complete item because the backlog is product-owned","Escalate directly to the executive sponsor and suspend all three decisions","Ask architecture to approve first because integration is the broadest concern","Route each decision to its authorized owner, coordinate dependencies among approvals, and escalate only unresolved conflicts."],"answer":[3],"why":["Product authority does not automatically include compliance or architecture decisions.","Escalation may be appropriate for unresolved conflicts but should not replace defined decision rights.","Architecture's scope does not supersede the other authorized approvals.","Correct: respects decision rights while coordinating the combined release decision."],"ref":"BABOK v3 §3.3 pp. 37–41; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q431","domains":[4],"level":2,"tag":"","q":"A retailer reports refunds take eight days. System data show a two-day median but a small, high-value segment waits twelve days. What should the BA do next?","opts":["Validate definitions and segment the data to understand the delayed cases and their causes","Use the median as the current state and set a two-day target","Use customer reports instead of the transaction data","Redesign the process around the majority who receive refunds quickly"],"answer":[0],"why":["Correct: validate measures and examine variation, causes, and affected stakeholder groups.","The median conceals the reported long-delay segment and is not automatically a target.","Both sources may be useful and should be reconciled rather than substituted blindly.","Redesign before understanding the delayed cases may preserve their root cause."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q432","domains":[4],"level":4,"tag":"","q":"A city wants fewer missed waste collections. Operations favors route optimization; customer service favors better exception handling. What should be established before selecting a solution?","opts":["The route optimization design and its acceptance criteria","Agree the desired outcomes, current-state causes, constraints, and future-state needs with both departments before comparing options.","A vendor shortlist that supports both preferred capabilities","A feature backlog ranked by each department's current preference"],"answer":[1],"why":["This selects one solution before the shared future state is agreed.","Correct: a shared understanding is needed before selecting designs, vendors, or features.","Vendor shortlisting is premature before desired outcomes and constraints are clear.","Preference ranking does not resolve differences in expected outcomes or boundaries."],"ref":"BABOK v3 §6.2 pp. 110–119; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q433","domains":[4],"level":5,"tag":"","q":"A supplier portal may reduce manual order entry, but suppliers have uneven connectivity and orders must continue during outages. What is the strongest risk analysis response?","opts":["Require continuous availability so the connectivity risk can be considered resolved","Reject the portal because any outage risk makes it infeasible","Assess outage likelihood and impact, then compare feasible mitigations and continuity options before recommending the portal.","Proceed with the portal and record connectivity as an implementation issue"],"answer":[2],"why":["A requirement does not remove the risk or establish that the design is feasible.","A risk does not automatically make an option infeasible; mitigation or contingency may be possible.","Correct: analyzes connectivity as a business risk instead of assuming it can be designed away or makes the option impossible.","Connectivity can affect adoption and continuity, so it belongs in analysis before commitment."],"ref":"BABOK v3 §6.3 pp. 120–123; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q434","domains":[4],"level":1,"tag":"","q":"An acquisition must combine customer records in six months. Processes are undocumented and union consultation is required. Which change-strategy element is most important to include early?","opts":["One final cutover date, with consultation included in communications","Immediate data conversion while process discovery runs in parallel","A requirement to complete process documentation before any planning","Define a change strategy covering data and process discovery, readiness, union consultation, dependencies, and a feasible cutover plan."],"answer":[3],"why":["A date alone leaves readiness, data risk, and consultation dependencies unmanaged.","Conversion before adequate process and data understanding creates avoidable risk and rework.","Planning can proceed with uncertainty tracked; complete documentation is not a prerequisite.","Correct: integrates the deadline with readiness, data, people, and consultation needs."],"ref":"BABOK v3 §6.4 pp. 124–130; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q435","domains":[4],"level":3,"tag":"","q":"A proposed warehouse change removes one approval step. Current-state analysis shows that step catches most incorrect hazardous-material labels, while the new scanner catches only common formats. What should the BA do before recommending the change?","opts":["Assess the control's purpose, error patterns, residual risk, and alternative future-state controls","Remove the approval because scanner capture is faster","Keep the approval unchanged because it detects errors","Add a general accuracy target to the scanner requirement and proceed"],"answer":[0],"why":["Correct: understand current control value and evaluate future-state alternatives and residual exposure.","Efficiency alone does not address the hazardous-material risk.","Keeping the control may be appropriate, but the decision should be based on analyzed options and risk.","A broad target may not cover error types or establish equivalent control effectiveness."],"ref":"BABOK v3 §§6.1, 6.4 pp. 103–109, 124–130; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q436","domains":[5],"level":1,"tag":"","q":"A hospital wants to understand why discharge instructions are misunderstood by patients and later repeated to nurses. Which elicitation preparation is best?","opts":["Survey nurses first because they handle the follow-up calls","Prepare neutral questions and involve patients and relevant staff to understand where instructions are misunderstood and why.","Draft revised instructions and interview patients to validate the wording","Ask the department head for one representative account and confirm it with a clinician"],"answer":[1],"why":["Nurses provide important evidence but cannot substitute for patient perspective or other sources.","Correct: gathers evidence from affected stakeholders before proposing revised wording.","This presumes the solution before understanding causes and needs.","A small set of proxy views may miss distinct experiences and causes."],"ref":"BABOK v3 §4.1 pp. 56–60; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q437","domains":[5],"level":2,"tag":"","q":"Operations and compliance give conflicting interpretations of an exception rule. What should the BA do to confirm the elicited information?","opts":["Adopt compliance's wording because it has regulatory authority","Combine both statements into a rule containing both conditions","Investigate the differing interpretations and evidence, clarify the authorized policy owner, and document the resolved rule and rationale.","Record both versions as approved and leave resolution to testing"],"answer":[2],"why":["Authority may decide policy, but the conflict and evidence should first be understood.","Combining incompatible statements can create a rule neither group intended.","Correct: conflicting information must be understood and resolved through appropriate authority before it is confirmed.","Contradictory information is not confirmed and should not be delegated to testing."],"ref":"BABOK v3 §4.3 pp. 65–66; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q438","domains":[5],"level":3,"tag":"","q":"A safety requirement depends on an uncertain migration. A lower-value report is independent, and capacity allows only one item this release. What is the best prioritization response?","opts":["Select safety because its value always outweighs feasibility","Select reporting because it is certain to complete","Defer both until migration certainty improves","Compare value, safety urgency, dependency, and feasibility; validate migration risk and prioritize safety with mitigation or sequencing if viable."],"answer":[3],"why":["Safety is important, but a dependency and feasibility risk affect when value can be delivered.","Certainty alone should not displace safety value or urgency.","Deferring both may be unnecessary if sequencing or a different option is viable.","Correct: considers value and urgency together with risk and feasibility rather than treating either as absolute."],"ref":"BABOK v3 §5.3 pp. 86–90; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q439","domains":[5],"level":4,"tag":"","q":"A regulator changes a reporting rule after requirements are approved. A shared definition, two designs, and an in-build interface may be affected. What should the BA do before recommending acceptance?","opts":["Assess value, dependencies, conflicts, and impacts across linked requirements and designs","Update the requirement and let each team identify impacts during delivery","Reject the change because the release baseline is approved","Use the vendor's interface estimate as the complete impact assessment"],"answer":[0],"why":["Correct: evaluate implications and conflicts across related requirements and designs before decision.","Changing one item without broader impact analysis risks omissions and rework.","An approved baseline does not eliminate the need to address changed regulatory context.","A vendor estimate covers effort, not full business, semantic, and cross-solution effects."],"ref":"BABOK v3 §5.4 pp. 91–94; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q440","domains":[5],"level":5,"tag":"","q":"A product workshop generates 60 requests. Several describe the same customer problem in different language; others are proposed features. The release decision is due tomorrow. What is the best next step?","opts":["Rank all requests by stakeholder seniority so a decision can be made on time","Group requests by underlying need, separate needs from proposed features, then apply agreed value, urgency, risk, and dependency criteria.","Convert every request into a user story and estimate them before grouping","Ask the sponsor to select the requests most likely to fit the release"],"answer":[1],"why":["Seniority is not a substitute for value, urgency, risk, or dependency criteria.","Correct: clustering and consistent criteria make requests comparable and reduce duplicate or premature solution work.","Estimating duplicates and solution proposals before clarifying needs can waste effort.","Sponsor input may be needed but should be based on clear, comparable needs."],"ref":"BABOK v3 §§4.2, 5.2 pp. 61–64, 83–85; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q441","domains":[6],"level":1,"tag":"","q":"A requirement is clear, testable, and approved, but users say it will not solve the reason the initiative was funded. Which review is most relevant?","opts":["Verification of its expression","Traceability to the implementation task","Validate the requirement against the business need and intended outcome with relevant stakeholders.","Approval by the solution owner"],"answer":[2],"why":["The issue is whether it addresses the need, not whether it is well formed.","Traceability shows relationships but does not prove that the right need is addressed.","Correct: the concern is whether the right need is addressed, which is validation.","Approval alone does not establish fit to need."],"ref":"BABOK v3 §7.3 pp. 144–147; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q442","domains":[6],"level":2,"tag":"","q":"A requirements package contains measurable criteria, but two criteria conflict and a dependent requirement has no owner. What should verification focus on?","opts":["Ask users whether the package represents the value they expect","Approve the package because each criterion is independently measurable","Defer consistency and ownership checks to solution testing","Verify consistency and completeness, identify the unowned dependency, and resolve conflicts and ownership before approval."],"answer":[3],"why":["This is important validation, but the immediate issues are requirement quality and internal consistency.","Individual measurability does not make a conflicting package coherent.","Testing does not replace verification of requirement quality before implementation.","Correct: verification checks quality and coherence, including conflicting criteria and missing ownership."],"ref":"BABOK v3 §7.2 pp. 141–143; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q443","domains":[6],"level":3,"tag":"","q":"Two options meet mandatory requirements. Option A has lower operating cost but high integration uncertainty; Option B costs more and uses a proven interface. What should the recommendation compare?","opts":["Potential value, lifecycle costs, feasibility, integration risk, and stakeholder impacts","Initial cost and delivery duration, then select the lower total","Stakeholder preference and vendor confidence, then select the better-supported option","Compliance coverage and functionality, treating integration risk as delivery-only"],"answer":[0],"why":["Correct: compare potential value with relevant costs, feasibility, risks, and stakeholder effects.","Initial cost and schedule omit lifecycle consequences and material integration uncertainty.","Preference and confidence matter but should be supported by comparative evidence.","Integration risk may affect feasibility and value, not merely delivery execution."],"ref":"BABOK v3 §§7.5–7.6 pp. 152–162; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q444","domains":[6],"level":4,"tag":"","q":"A scheduling solution meets documented rules but requires manual workarounds during seasonal peaks. What should solution evaluation examine?","opts":["Whether users complied with the rules before reviewing the platform","Evaluate the workaround’s frequency, cost, risk, and effect on peak outcomes, then identify the gap and response options.","Whether the workaround can be documented as acceptable procedure","Whether requirements should be relaxed to match current platform limits"],"answer":[1],"why":["User compliance does not resolve a platform limitation.","Correct: evaluation should establish performance and stakeholder impact before deciding whether a workaround is acceptable.","Documentation does not establish the workaround's cost, risk, or acceptability.","Relaxing needs to fit a limitation may undermine the business outcome."],"ref":"BABOK v3 §8.3 pp. 173–176; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q445","domains":[6],"level":5,"tag":"","q":"A vendor's screening option projects the largest savings, assuming 95% adoption; comparable deployments achieved 60–70%. It also risks excluding applicants with thin credit files. What is the strongest recommendation basis?","opts":["Use the vendor forecast because it is specific to the proposed product","Reject the option because its adoption estimate exceeds the historical range","Test the recommendation across realistic adoption scenarios and assess potential exclusion impacts before comparing value and risk.","Choose the option with the lowest forecast variance regardless of expected outcome"],"answer":[2],"why":["Product-specific projections still depend on assumptions that need validation and may omit stakeholder impacts.","Historical results inform scenarios but do not prove higher adoption is impossible.","Correct: sensitivity analysis addresses uncertain adoption while stakeholder impact informs the recommendation.","Forecast stability alone does not establish value or address potential exclusion."],"ref":"BABOK v3 §§7.3, 8.1–8.2 pp. 144–147, 166–172; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q446","domains":[7],"level":1,"tag":"","q":"A pension platform affects retirees, HR, payroll, a regulator, and a processing partner. What is the best first stakeholder action?","opts":["Invite all named groups to one workshop and let them select representatives","Start with the sponsor's contacts and add groups if concerns arise","Map decision-makers and assume they represent other affected parties","Identify and analyze affected stakeholders, interests, decision roles, influence, and engagement needs, including external groups."],"answer":[3],"why":["A workshop may not be appropriate for every stakeholder or provide complete representation.","Sponsor contacts can omit affected stakeholders and sources of requirements.","Decision authority does not mean a role represents every impacted group.","Correct: systematic stakeholder analysis reveals affected groups and decision responsibilities before engagement is planned."],"ref":"BABOK v3 §10.43 p. 344; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q447","domains":[7],"level":2,"tag":"","q":"A remote operations lead has unique process knowledge but cannot attend scheduled daytime sessions. What is the best adjustment?","opts":["Arrange asynchronous or alternate-time elicitation and confirm the lead's input directly","Ask managers to represent the lead and validate the summary later","Send notes to the lead and treat silence as confirmation","Remove the lead from engagement because availability is limited"],"answer":[0],"why":["Correct: tailor collaboration to availability while retaining direct input from a relevant stakeholder.","Managers may not have the same first-hand knowledge.","Silence is not confirmation and notes do not elicit missing details.","Limited availability does not make the stakeholder irrelevant."],"ref":"BABOK v3 §3.2 pp. 31–36; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q448","domains":[7],"level":3,"tag":"","q":"Sales, finance, and analytics use different definitions of active customer. The definition affects commissions and regulatory reporting. What workshop outcome should the facilitator seek?","opts":["Adopt the definition used most frequently across the three groups","Use examples and impact analysis to agree a shared definition, decision rules, and accountable owner before implementation.","Ask the sponsor to state the preferred definition before discussing examples","Have each group finalize its model separately and reconcile after implementation"],"answer":[1],"why":["Frequency does not resolve material differences in meaning or consequences.","Correct: examples and consequences help resolve differences affecting commissions and reporting.","A preferred definition may bias analysis before stakeholder evidence is explored.","Separate models can preserve inconsistency and defer a consequential conflict."],"ref":"BABOK v3 §10.50 p. 363; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q449","domains":[7],"level":4,"tag":"","q":"A department head endorses a new workflow publicly but privately tells staff to keep using the old process. What should the BA do?","opts":["Record the head as resistant and escalate to the sponsor","Treat public support as sufficient and continue rollout communications","Discuss the observed gap with the department head, understand reasons and barriers, and agree an engagement and adoption response.","Ask staff to follow the new workflow without involving the head"],"answer":[2],"why":["Escalation before understanding the concern may worsen the relationship and miss a solvable barrier.","Observed behavior indicates adoption barriers despite public statements.","Correct: addresses the inconsistency and its cause before escalation or rollout decisions.","Bypassing a key stakeholder can deepen resistance and leave its cause unaddressed."],"ref":"BABOK v3 §4.5 pp. 71–75; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q450","domains":[7],"level":5,"tag":"","q":"A regulator sets minimum identity controls; customer advocates report exclusion; product leaders warn of abandonment. How should the BA facilitate the decision?","opts":["Use the minimum control as the only requirement and treat other impacts as optional","Use customer preference as the deciding criterion because value is customer-defined","Let product leadership select the option that minimizes abandonment","Keep the regulatory minimum as a constraint, then compare compliant options against exclusion, abandonment, and other stakeholder outcomes."],"answer":[3],"why":["Compliance is mandatory but does not resolve other stakeholder outcomes or feasible alternatives.","Customer value matters but cannot override regulatory constraints or other relevant impacts.","One product metric is insufficient for a multi-stakeholder decision.","Correct: meets mandatory controls while evaluating impacts and value across feasible alternatives."],"ref":"BABOK v3 §§3.2, 4.5 pp. 31–36, 71–75; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q451","domains":[8],"level":1,"tag":"","q":"A licensing service aims to reduce avoidable repeat visits. Which measure most directly evaluates the intended outcome?","opts":["Share of applicants completing without an avoidable repeat visit within a defined period","Number of screens removed from the redesigned service","Number of staff trained before launch","Average time spent on the application regardless of completion"],"answer":[0],"why":["Correct: it measures the intended outcome and defines an observation period.","Screen count measures a design change, not customer outcome.","Training counts readiness activity, not repeat visits.","Time may be useful but does not directly establish fewer repeat visits."],"ref":"BABOK v3 §8.1 p. 166; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q452","domains":[8],"level":2,"tag":"","q":"The board objective is to reduce preventable service failures, but the dashboard tracks tickets closed per agent. What is the best improvement?","opts":["Raise the closures-per-agent target to reflect the board's priority","Define measures that directly reflect preventable failures, with diagnostic measures and relevant segments.","Replace the KPI with customer satisfaction alone","Use average handling time because it is collected consistently"],"answer":[1],"why":["Increasing throughput can reward speed without reducing preventable failures.","Correct: measures should align with the desired outcome and reveal whether and why failures change.","Satisfaction can complement but may not identify failure rates or causes.","Handling time is not a direct indicator and may create conflicting incentives."],"ref":"BABOK v3 §10.28 p. 297; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q453","domains":[8],"level":3,"tag":"","q":"A pilot reduces average onboarding time by 20%, while international customer failure rates rise and domestic failure rates fall. What should the BA report?","opts":["The target was achieved because the aggregate average improved","The pilot failed because one segment worsened","Report aggregate and segment results, investigate international failures and domestic improvement, and assess causes and response options.","Exclude international cases because they form a smaller share"],"answer":[2],"why":["The aggregate can conceal materially different outcomes across stakeholder groups.","A worsened segment is important but does not alone characterize all outcomes or response options.","Correct: preserves the overall result while making material differences visible for evaluation.","A smaller group may still experience significant impact and should not be omitted without justification."],"ref":"BABOK v3 §§8.1–8.2 pp. 166–172; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q454","domains":[8],"level":4,"tag":"","q":"A service's average response time improves, but the slowest 10% of cases worsen substantially. The original KPI was the mean. What is the best analysis?","opts":["Confirm success against the agreed mean and report the tail as context","Replace the KPI retroactively with a percentile and restate the target","Exclude the slowest cases as outliers unless they exceed a legal limit","Retain the agreed mean for the original assessment, add tail measures for diagnosis, and investigate worsening cases and impacts."],"answer":[3],"why":["The agreed mean matters, but it may conceal a material worsening that affects value.","A different measure may help, but retroactively changing the target can distort the assessment.","Outlier treatment needs evidence; significant stakeholder impacts cannot be discarded by default.","Correct: supplementary measures reveal tail impact without silently changing the original success criterion."],"ref":"BABOK v3 §8.2 pp. 170–172; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q455","domains":[8],"level":5,"tag":"","q":"A self-service capability is available, but only 18% of eligible customers use it against a 65% business-case assumption. What should the BA advise?","opts":["Reassess value using observed adoption and investigate barriers before selecting further action","Keep the business case unchanged until a full year of data is collected","Increase promotion immediately and retain the adoption assumption","Conclude the solution failed and begin replacement selection"],"answer":[0],"why":["Correct: use current evidence to assess realized value and understand addressable barriers.","Waiting may prolong a value gap when current evidence is already informative.","Promotion may be an option, but it should follow barrier analysis; the assumption needs review.","Low adoption is evidence of a problem but does not prove replacement is best."],"ref":"BABOK v3 §8.5 pp. 182–186; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q456","domains":[9],"level":1,"tag":"","q":"A proposed data platform may conflict with a new residency rule; legal interpretation is pending. How should the BA treat the issue?","opts":["Treat the prohibition as confirmed and remove the platform","Record the pending interpretation as uncertainty and risk, seek legal validation, and assess implications for options and timing meanwhile.","Ignore the possibility until legal issues a final opinion","Classify the possibility as a non-functional requirement and proceed"],"answer":[1],"why":["The rule is not confirmed, so eliminating an option may be premature.","Correct: the issue is unconfirmed but can affect feasibility and should be managed while validation proceeds.","The possibility can already affect risk and feasibility analysis.","The rule may constrain the solution, but its meaning and classification require validation."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q457","domains":[9],"level":2,"tag":"","q":"A checkout solution depends on inventory, fraud screening, payment providers, and a tax service with separate release calendars. What should context analysis emphasize?","opts":["The checkout boundary and internal requirements only","The vendors' contracts because interface behavior can be tested later","Map the solution boundary, external actors, interfaces, data flows, operating dependencies, and release timing across providers.","Data flows only, leaving release timing to project planning"],"answer":[2],"why":["An internal-only boundary omits dependencies that may prevent end-to-end value.","Testing does not replace early analysis of integration and operating dependencies.","Correct: context analysis includes external dependencies and timing that affect end-to-end behavior.","Release timing can constrain integration and is part of the context."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q458","domains":[9],"level":3,"tag":"","q":"Corporate policy requires dual approval for high-risk payments. A product team proposes single-click release because usability tests favor it. What should the BA recommend?","opts":["Accept the test evidence and defer the control to operations","Retain the current dual-approval implementation without comparing alternatives","Ask customers to choose whether the control should remain","Preserve required dual approval while exploring a more usable compliant workflow with the control owner."],"answer":[3],"why":["Usability evidence does not authorize removal of an organizational control.","The control may be mandatory, but its implementation can still be improved.","Customers cannot decide whether an applicable control is required.","Correct: the control remains mandatory, while its implementation can be improved and assessed with its owner."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q459","domains":[9],"level":4,"tag":"","q":"A local solution meets team needs but cannot exchange records with the enterprise identity service mandated by corporate policy. Which issue is most relevant?","opts":["An enterprise-context constraint shaping which solution designs are feasible","A solution limitation because the product lacks an interface","A stakeholder limitation because users did not request integration","A transition requirement because the identity service is already deployed"],"answer":[0],"why":["Correct: enterprise policy and shared services are context factors that constrain the solution.","The technical gap matters, but the binding policy and shared service shape feasibility at enterprise level.","A missing local request does not remove an enterprise requirement.","Existing service integration is not automatically a transition requirement."],"ref":"BABOK v3 §8.4 pp. 177–181; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q460","domains":[9],"level":5,"tag":"","q":"A merger must comply with two privacy regimes, preserve service continuity, and integrate systems before a regulator's deadline. Local legal analyses will finish at different times. What is the strongest planning response?","opts":["Use one standard migration plan and document jurisdiction exceptions during execution","Plan around the deadline while tracking jurisdiction privacy decisions, continuity needs, dependencies, and contingencies as analyses complete.","Prioritize the deadline and resolve privacy and continuity conflicts as they arise","Wait until all local analyses are complete before forming a program plan"],"answer":[1],"why":["A standard plan without early constraint analysis can create compliance and continuity failures.","Correct: planning can proceed with known constraints and uncertainty tracked while incorporating local decisions in time.","Deferring known conflicts risks a late or infeasible transition.","Planning can proceed with uncertainty and validation tracked explicitly; it need not wait entirely."],"ref":"BABOK v3 §§3.1, 6.1 pp. 24–30, 103–109; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q461","domains":[5],"level":1,"tag":"Business need","q":"A retailer is losing customers because online orders often arrive late. The sponsor asks the business analyst to recommend a new delivery-tracking system immediately. What should the business analyst clarify first?","opts":["Which vendor has the most features","The business need the change is intended to address","The technical design of the tracking system","The training plan for delivery staff"],"answer":[1],"why":["This could inform a later solution assessment, but choosing a vendor before understanding the need is premature.","Correct. Business analysis begins by defining needs and recommending solutions that deliver value in context.","A design is a solution detail. First clarify the problem or opportunity the change must address.","Training may be needed for a chosen solution, but it does not clarify the underlying business need."],"ref":"Chapter 2, §2.1 Defining Business Analysis, p. 5","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q462","domains":[5],"level":1,"tag":"Approaches","q":"A team is working in a fast-changing market. It expects to learn more about customer needs as it develops the product and plans to adjust its work frequently. Which approach best fits this situation?","opts":["Predictive","Adaptive","Fixed","Sequential"],"answer":[1],"why":["Predictive work plans more of the work in advance; it is less suited when frequent learning and adjustment are expected.","Correct. Adaptive approaches accommodate evolving understanding and changes as work progresses.","Fixed is not one of the three approaches described in the Standard (predictive, adaptive, and hybrid).","Sequential describes an ordering of work, but it is not the approach that best reflects ongoing adaptation."],"ref":"Chapter 4, §4.2 Approaches to Business Analysis Work, pp. 13–14","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q463","domains":[7],"level":2,"tag":"Value","q":"During a workshop, a stakeholder suggests a solution that would benefit their department but may not support the organization’s objectives. What should the business analyst do?","opts":["Accept the suggestion because the stakeholder owns the process","Compare the suggestion with the business need and expected value","Defer the decision to the implementation team","Add it to the solution scope without further analysis"],"answer":[1],"why":["Stakeholder input matters, but one department’s preference does not by itself establish enterprise value.","Correct. Assess the suggestion in context against the need, objectives, and value for stakeholders.","The implementation team may provide useful input, but this does not replace analysis of business value.","Adding it without analysis risks expanding scope without confirming that it supports the business need."],"ref":"Chapter 2, §2.5 Outcomes and Value Creation, p. 7","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q464","domains":[5],"level":1,"tag":"Verification","q":"A business analyst has documented requirements and wants to confirm that they are clear, consistent, and usable as a basis for further work. Which activity is most appropriate?","opts":["Validate requirements and designs","Verify requirements and designs","Assess solution limitations","Measure solution performance"],"answer":[1],"why":["Validation checks alignment with business objectives and expected value; it is not the primary quality check described here.","Correct. Verification ensures requirements and designs are defined correctly, internally consistent, and usable for their purpose.","Solution limitations are considered when evaluating a solution, not when checking the quality of requirement specifications.","Performance measurement evaluates a solution in operation rather than checking requirement quality before further work."],"ref":"Chapter 5, Verify Requirements and Designs, p. 43","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q465","domains":[8],"level":2,"tag":"Validation","q":"Users review a proposed design and confirm that it supports the business goals and is expected to deliver the needed value. Which activity are they performing?","opts":["Verification","Validation","Elicitation preparation","Requirements tracing"],"answer":[1],"why":["Verification checks that the specification is sufficiently clear and of quality; it does not primarily assess alignment with business value.","Correct. Validation confirms that requirements and designs align with business goals and support value delivery.","Preparation happens before elicitation, not when users assess whether a design supports objectives.","Tracing manages relationships among requirements and designs; it does not establish that they deliver business value."],"ref":"Chapter 5, Validate Requirements and Designs, p. 44","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q466","domains":[5],"level":3,"tag":"Requirements architecture","q":"A project has several requirements and designs that appear individually reasonable, but the team is unsure whether they work together to support the business objectives. What should the business analyst focus on?","opts":["Requirements architecture","Solution performance measures","Stakeholder engagement approach","Elicitation results"],"answer":[0],"why":["Correct. Requirements architecture structures requirements and designs and shows how they relate as a cohesive whole supporting the objectives.","Performance measures assess solution results, usually after or during solution use; they do not structure the requirements together.","Stakeholder engagement guides working with stakeholders but does not show how the requirements and designs fit together.","Elicitation results are information gathered from stakeholders; the issue is how requirements and designs collectively support the business purpose."],"ref":"Chapter 5, Define Requirements Architecture, p. 45","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q467","domains":[8],"level":3,"tag":"Potential value","q":"A team is comparing options to meet a business need. One option has lower implementation cost but higher operational risk; another costs more but may provide greater benefits. What should the business analyst do?","opts":["Recommend the least expensive option","Recommend the option with the fewest requirements","Compare potential value, costs, benefits, risks, and constraints","Let the implementation team choose after development begins"],"answer":[2],"why":["Lowest cost alone does not account for benefits, risk, constraints, or total potential value.","The number of requirements does not determine which option best meets the business need.","Correct. Compare options and trade-offs, including benefits, associated costs, and identified constraints; risk analysis also informs the recommendation.","Deferring the choice until development begins avoids the analysis needed to recommend an appropriate option."],"ref":"Chapter 5, Analyze Potential Value and Recommend Solution, p. 47","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q468","domains":[4],"level":2,"tag":"Change strategy","q":"An organization wants to move from its current customer service process to a desired future state. It is considering a series of smaller changes or one large transformation. Which task addresses selecting and describing the approach to make this transition?","opts":["Define Change Strategy","Analyze Current State","Specify and Model Requirements and Designs","Communicate Business Analysis Information"],"answer":[0],"why":["Correct. This task assesses alternative approaches to change, recommends an approach, and may include transition states.","Analyzing current state helps understand the existing situation, but does not select the approach for reaching the future state.","This task refines elicitation results into requirements and designs; it does not determine the overall transition approach.","Communication supports shared understanding but does not define the change approach itself."],"ref":"Chapter 5, Define Change Strategy, p. 41","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q469","domains":[8],"level":2,"tag":"Risk","q":"A business analyst is assessing a proposed change and identifies uncertainties that could prevent the organization from achieving value. Which task is the best fit?","opts":["Define Future State","Assess Risks","Maintain Requirements and Designs","Approve Requirements and Designs"],"answer":[1],"why":["Defining future state establishes desired conditions and objectives; the question is about uncertainty and its effects.","Correct. Assess Risks considers uncertainties and their potential consequences during transition to, or operation in, a future state.","Maintenance keeps requirements and designs accurate and reusable as they change; it does not assess the uncertainties described.","Approval obtains authorization for requirements and designs, rather than analyzing the risks to value delivery."],"ref":"Chapter 5, Assess Risks, p. 40","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q470","domains":[7],"level":2,"tag":"Requirements analysis","q":"A team has gathered information from stakeholders and now needs to analyze and refine it into requirements and designs using suitable text, matrices, or diagrams. Which task should it perform?","opts":["Conduct Elicitation","Confirm Elicitation Results","Specify and Model Requirements and Designs","Analyze Potential Value and Recommend Solution"],"answer":[2],"why":["Conduct Elicitation gathers information from stakeholders; the information has already been gathered in this scenario.","Confirming elicitation results checks understanding and accuracy of what was elicited, rather than refining it into detailed requirements and designs.","Correct. This task analyzes, synthesizes, and refines elicitation results into requirements and designs, which may be expressed as text, matrices, or diagrams.","This task compares design options and recommends a solution based on potential value, rather than specifying the requirements and designs."],"ref":"Chapter 5, Specify and Model Requirements and Designs, p. 42","multi":false,"sourceSet":"ecba-practice-simulator.html"},{"id":"q471","domains":[2],"level":1,"tag":"","q":"When the right next step is not immediately obvious, which mindset is most useful?","opts":["Remain open and adaptable while selecting an appropriate way to proceed","Apply the same analysis process regardless of context","Wait until all uncertainty is removed before acting","Use the most familiar technique even when it does not fit the need"],"answer":[0],"why":["Correct: an empowering mindset helps practitioners navigate situations where the exact next step is not known.","The Standard says each situation is unique and does not prescribe a single approach.","Complete certainty is not always possible; adaptability helps professionals work through uncertainty.","Familiarity alone does not establish that a technique is appropriate to the context."],"ref":"The Business Analysis Standard v2.0 §3.1, printed p. 9; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q472","domains":[2],"level":1,"tag":"","q":"Which statement best reflects the Standard’s view of business analysis work?","opts":["It follows a single universal sequence of steps","It combines appropriate techniques, processes, and tools to achieve desired outcomes","It focuses on documenting requirements before considering change","It is primarily a technology-selection activity"],"answer":[1],"why":["The Standard emphasizes a flexible approach rather than one universal sequence.","Correct: business analysis is human-centred and creative, selecting appropriate techniques, processes, and tools to achieve outcomes and change.","Requirements work is only one part of business analysis and does not replace understanding outcomes.","Technology may support change but does not define the business analysis work."],"ref":"The Business Analysis Standard v2.0 §3.1–3.2, printed pp. 9–10; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q473","domains":[2],"level":1,"tag":"","q":"Which outcomes can be supported by an empowering business analysis mindset?","opts":["High-quality outcomes","Empathy and continual learning from impacted stakeholders","Prioritizing focus","Eliminating stakeholder collaboration to speed decisions"],"answer":[0,1,2],"why":["Correct: creating high-quality outcomes is an identified capability.","Correct: the Standard highlights empathy and learning from impacted stakeholders.","Correct: prioritizing focus is one of the capabilities supported by an empowering mindset.","Collaboration is encouraged as a way to build allies for change."],"ref":"The Business Analysis Standard v2.0 §3.1, printed p. 9; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q474","domains":[2],"level":1,"tag":"","q":"Which option identifies the shared values of business analysis work?","opts":["Respect, courage, collaboration, ethics, curiosity, continuous learning, improvement, customer focus, and value maximization","Respect, compliance, speed, standardization, control, predictability, and efficiency","Courage, competition, individual ownership, certainty, uniformity, and cost minimization","Customer focus, schedule adherence, risk avoidance, consistency, and solution delivery"],"answer":[0],"why":["Correct: these are the shared values listed in Section 3.2.","Some items may be useful in practice but this is not the list of shared values in the Standard.","This set includes terms not listed as shared values and omits several that are.","This set includes useful goals but does not reproduce the stated shared values."],"ref":"The Business Analysis Standard v2.0 §3.2, printed p. 9; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q475","domains":[2],"level":2,"tag":"","q":"Which statements explain how mindset is developed and used?","opts":["Habits, attitudes, behaviours, and practices contribute to an empowering mindset","Mindset is an innate quality that cannot be deliberately developed","A flexible mindset supports adapting to context and feedback","Mindset is separate from how teams make decisions"],"answer":[0,2],"why":["Correct: the Standard describes these habits and practices as needed to navigate uncertain situations.","Mindset can be developed with deliberate practice.","Correct: assessing context and adapting to realities and feedback are supported capabilities.","Mindset influences decision-making, behaviour, and team dynamics."],"ref":"The Business Analysis Standard v2.0 §3.1, printed p. 9; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q476","domains":[2],"level":2,"tag":"","q":"Which activities are identified as deliberate practices for developing an empowering mindset?","opts":["Discovering value for stakeholders","Deciding how to approach the work","Adopting appropriate business analysis principles","Avoiding the use of foundational techniques"],"answer":[0,1,2],"why":["Correct: discovering stakeholder value is one deliberate practice.","Correct: deciding how to approach the work is included.","Correct: adopting appropriate BA principles is included.","The Standard includes being able to use foundational techniques, not avoiding them."],"ref":"The Business Analysis Standard v2.0 §3.1, printed p. 9; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q477","domains":[2],"level":2,"tag":"","q":"Which statements describe the way business analysis is framed in Section 3.2?","opts":["It is human-centred","It is creative","It aims to achieve desired outcomes and drive organizational change","It is limited to producing a documented solution specification"],"answer":[0,1,2],"why":["Correct: the Standard calls business analysis human-centred.","Correct: it describes business analysis as a creative process.","Correct: its aim includes desired outcomes and organizational change.","Documentation can support analysis but is not the full purpose of the work."],"ref":"The Business Analysis Standard v2.0 §3.2, printed pp. 9–10; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q478","domains":[2],"level":2,"tag":"","q":"Which pairs are included among the shared values?","opts":["Curiosity and continuous learning","Improvement and customer focus","Ethics and value maximization","Efficiency and strict standardization"],"answer":[0,1,2],"why":["Correct: both curiosity and continuous learning are listed.","Correct: both improvement and customer focus are listed.","Correct: ethics and value maximization are listed shared values.","Efficiency and strict standardization are not the listed pair of shared values."],"ref":"The Business Analysis Standard v2.0 §3.2, printed pp. 9–10; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q479","domains":[2],"level":3,"tag":"","q":"Which statement best describes the principle “See the whole”?","opts":["Analyze needs in the big-picture context and understand why change is necessary","Start by detailing a solution before considering the need","Focus on the immediate requirement and exclude wider stakeholders","Treat the current process as fixed context"],"answer":[0],"why":["Correct: the principle calls for big-picture context and understanding why change is necessary.","This starts with a solution and omits the need.","The principle requires a broader view of context, solution, and stakeholders.","Context includes circumstances relevant to change and should be analyzed."],"ref":"The Business Analysis Standard v2.0 §3.3, printed pp. 10–11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q480","domains":[2],"level":3,"tag":"","q":"Which practices align with “Think as a customer”?","opts":["Understand customer experience needs","Move from high-level customer needs to detailed understanding","Use the sponsor’s perspective as a substitute for customer needs","Treat customer needs as fixed once first documented"],"answer":[0,1],"why":["Correct: the principle emphasizes understanding customer experience needs.","Correct: it describes progressing from a high-level view to detailed understanding that guides an evolving solution.","A sponsor’s view does not substitute for understanding customer needs.","Understanding can evolve as the team learns; the principle does not require treating needs as fixed."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q481","domains":[2],"level":3,"tag":"","q":"Which actions align with “Analyze to determine what is valuable”?","opts":["Continuously assess and prioritize work","Maximize the value being delivered","Use context, needs, stakeholders, and solution possibilities to understand value","Prioritize only by the order requests were received"],"answer":[0,1,2],"why":["Correct: continuous assessment and prioritization are part of this principle.","Correct: the principle aims to maximize delivered value.","Correct: value is understood through context, needs, stakeholders, and solution possibilities.","Order of receipt is not the value-based prioritization described by the principle."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q482","domains":[2],"level":3,"tag":"","q":"Which statement best captures “Get real using examples”?","opts":["Use real examples to build shared understanding and support solution analysis","Use examples only after the solution design is complete","Replace stakeholder discussion with examples","Use examples only to document final requirements"],"answer":[0],"why":["Correct: examples support shared understanding of the need and how a solution may satisfy it.","Examples can inform design and testing before a design is complete.","Examples support collaboration and do not replace stakeholder engagement.","Examples can also support acceptance criteria, design, and testing."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q483","domains":[2],"level":4,"tag":"","q":"Which statements reflect the principle “Understand what is doable”?","opts":["Consider delivery constraints while analyzing needs and solutions","Consider constraints in the operational environment","Ensure the solution can deliver its intended value within constraints","Treat a valuable idea as feasible without examining constraints"],"answer":[0,1,2],"why":["Correct: the principle calls for understanding how to deliver within constraints.","Correct: operational-environment constraints are specifically noted.","Correct: constraints matter to whether the intended value can be delivered.","Value does not eliminate the need to assess feasibility and constraints."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q484","domains":[2],"level":4,"tag":"","q":"Which practices support collaboration and continuous improvement?","opts":["Create an environment where stakeholders contribute to value on an ongoing basis","Use feedback to adapt the solution and its processes","Limit collaboration to the initial elicitation stage","Use continuous improvement to increase delivered value"],"answer":[0,1,3],"why":["Correct: ongoing stakeholder contribution is part of this principle.","Correct: continuous feedback can adapt solutions and processes.","The principle describes ongoing contribution, not a one-time collaboration stage.","Correct: continuous improvement aims to increase delivered value."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q485","domains":[2],"level":4,"tag":"","q":"What does “Avoid waste” call for?","opts":["Identify activities that add value and those that do not","Remove activities that do not contribute to satisfying the need","Remove every activity that does not create a visible product feature","Retain activities even when they add no value to the need"],"answer":[0,1],"why":["Correct: identifying value-adding and non-value-adding activities is part of the principle.","Correct: the principle calls for removing activities that do not contribute to satisfying the need.","Some analysis activities add value by improving understanding or decisions without producing a feature.","The principle encourages removing work that does not contribute to satisfying the need."],"ref":"The Business Analysis Standard v2.0 §3.3, printed p. 11; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q486","domains":[2],"level":4,"tag":"","q":"Which statements about foundational competencies are accurate?","opts":["They are basic skills, abilities, and characteristics needed for effective business analysis","They can be applied in different contexts and across different initiatives","They are relevant only to business analysts with a formal BA job title","The BABOK Guide describes 29 underlying competencies"],"answer":[0,1,3],"why":["Correct: this is the Standard’s description of foundational competencies.","Correct: underlying competencies apply in many contexts and initiative types.","The Standard describes competencies for business analysis professionals broadly, not only a job title.","Correct: the Standard notes that the BABOK Guide describes 29 underlying competencies."],"ref":"The Business Analysis Standard v2.0 §3.4, printed pp. 11–12; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q487","domains":[2],"level":5,"tag":"","q":"Which statement best describes adaptability as a foundational competency?","opts":["Adjusting behavioural style to increase effectiveness","Guiding stakeholders to the desired value through consensus","Holistically understanding the enterprise and context","Ensuring value addresses the root cause of a problem"],"answer":[0],"why":["Correct: this is the Standard’s description of adaptability.","This describes leadership and influencing.","This describes systems thinking.","This describes problem solving."],"ref":"The Business Analysis Standard v2.0 §3.4, printed p. 12; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q488","domains":[2],"level":5,"tag":"","q":"Which competency-description pairs are accurate?","opts":["Facilitation — facilitating workshops, negotiating, and helping resolve conflicts","Leadership and influencing — building consensus and guiding stakeholders toward desired value","Problem solving — ensuring created value addresses root causes","Systems thinking — adjusting behavioural style to increase effectiveness"],"answer":[0,1,2],"why":["Correct: these activities are included in the description of facilitation.","Correct: consensus building and guiding stakeholders are included in the description.","Correct: problem solving focuses on ensuring value addresses root causes.","Adjusting behavioural style is the description of adaptability."],"ref":"The Business Analysis Standard v2.0 §3.4, printed p. 12; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q489","domains":[2],"level":5,"tag":"","q":"Which statement best explains why ongoing stakeholder engagement matters to foundational competencies?","opts":["It supports shared understanding of the change effort, value to be discovered, and work needed to drive change","It is needed only to secure final approval of a solution","It replaces the need to develop individual competencies","It is useful only when stakeholders disagree"],"answer":[0],"why":["Correct: the Standard identifies ongoing engagement as necessary for shared understanding of the change, value, and work.","Engagement is ongoing and supports more than final approval.","Engagement and competency development complement one another.","Ongoing engagement is valuable even when stakeholders do not disagree."],"ref":"The Business Analysis Standard v2.0 §3.4, printed p. 12; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":false,"sourceSet":"ecba-set-10.html"},{"id":"q490","domains":[2],"level":5,"tag":"","q":"Which practices together reflect an effective business analysis mindset?","opts":["Adapt the approach to context and feedback","Use principles to focus analysis on outcomes and value","Develop competencies and techniques needed for the work","Apply the same process and tools to every initiative"],"answer":[0,1,2],"why":["Correct: adaptability to context and feedback is central to the mindset.","Correct: the principles focus analysis on outcomes and value.","Correct: deliberate competency and technique development supports effective work.","The Standard states that no single approach fits every situation."],"ref":"The Business Analysis Standard v2.0 §3.1–3.4, printed pp. 9–12; ECBA Exam Blueprint v1.12 p. 2, Domain 2","multi":true,"sourceSet":"ecba-set-10.html"},{"id":"q491","domains":[3],"level":1,"tag":"","q":"Which statement best reflects how business analysis relates to organizational roles?","opts":["It is performed only by staff assigned to a formal BA position","It is a versatile skill set that can improve work across many roles","It is reserved for people who own the solution design","It is limited to initiatives with a dedicated BA department"],"answer":[1],"why":["A formal BA title is not required to apply business analysis.","Correct: the Standard describes business analysis as a versatile skill set applicable to any role.","Solution ownership is not a prerequisite for using BA skills.","Organizations may deliver BA in several ways; a dedicated department is not required."],"ref":"The Business Analysis Standard v2.0 §4.1, printed p. 13; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":false,"sourceSet":"ecba-set-11.html"},{"id":"q492","domains":[3],"level":1,"tag":"","q":"Which work may benefit from business analysis?","opts":["Developing enterprise strategy, goals, and outcomes","Facilitating stakeholder collaboration and engagement","Designing new processes or improving existing ones","Only recording approved requirements for a technology project"],"answer":[0,1,2],"why":["Correct: understanding and developing strategy, goals, objectives, and outcomes is listed.","Correct: stakeholder collaboration and engagement are listed areas of application.","Correct: designing or improving processes is included.","Business analysis applies beyond technology projects and requirements recording."],"ref":"The Business Analysis Standard v2.0 §4.1, printed p. 13; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"}]);